import { Router } from 'express'
import bcrypt from 'backend/node_modules/bcryptjs'
import jwt from 'jsonwebtoken'
import dotenv from 'dotenv'
import pool from 'backend/src/db.js'
import { requireAuth } from 'backend/src/middleware/require-auth.js'

dotenv.config()
const router = Router()

router.post('/login', async (req, res, next) => {
  try {
    const nexId = String(req.body?.nexId || '').trim().toUpperCase()
    const password = String(req.body?.password || '')

    if (!nexId || !password) {
      return res.status(400).json({ message: 'Enter your NEX ID and password.' })
    }
    if (nexId.length > 40 || password.length > 200) {
      return res.status(400).json({ message: 'Invalid NEX ID or password.' })
    }

    const [rows] = await pool.execute(
      'SELECT id, nex_id, full_name, password_hash, role, is_active FROM users WHERE nex_id = ? LIMIT 1',
      [nexId]
    )
    const user = rows[0]
    const validPassword = user ? await bcrypt.compare(password, user.password_hash) : false

    if (!user || !validPassword || !user.is_active) {
      return res.status(401).json({ message: 'Incorrect NEX ID or password.' })
    }

    if (!process.env.JWT_SECRET || process.env.JWT_SECRET.length < 32) {
      return res.status(500).json({ message: 'Server authentication is not configured.' })
    }

    const token = jwt.sign(
      { sub: String(user.id), nexId: user.nex_id, role: user.role },
      process.env.JWT_SECRET,
      { expiresIn: process.env.JWT_EXPIRES_IN || '8h' }
    )

    res.json({
      message: 'Login successful.',
      token,
      user: { id: user.id, nexId: user.nex_id, name: user.full_name, role: user.role },
    })
  } catch (error) {
    next(error)
  }
})

router.get('/me', requireAuth, async (req, res, next) => {
  try {
    const [rows] = await pool.execute(
      'SELECT id, nex_id, full_name, role, is_active FROM users WHERE id = ? LIMIT 1',
      [req.user.sub]
    )
    const user = rows[0]
    if (!user || !user.is_active) {
      return res.status(401).json({ message: 'Account is unavailable.' })
    }
    res.json({ user: { id: user.id, nexId: user.nex_id, name: user.full_name, role: user.role } })
  } catch (error) {
    next(error)
  }
})

export default router
